/**
 *
 * DataTableRowEditor provides a container and context for row editing buttons inside a DataTable.
 * Use with DataTableRowEditorInit, DataTableRowEditorSave, and DataTableRowEditorCancel.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableRowEditor
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseDataTableEditingEvent, UseDataTableRowEditEvent } from '@primereact/types/headless/datatable';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableRowEditor component.
 */
export type DataTableRowEditorPassThroughType<E> = PassThroughType<DataTableRowEditorInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableRowEditor component.
 */
export interface DataTableRowEditorPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableRowEditorPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in DataTableRowEditor component.
 */
export interface DataTableRowEditorProps extends BaseComponentProps<DataTableRowEditorInstance, unknown, DataTableRowEditorPassThrough, 'div'> {
    /**
     * Row key used for editing state tracking.
     */
    rowKey: string | number;
    /**
     * The row data — forwarded to `onRowEditInit` / `onRowEditSave` / `onRowEditCancel` events so
     * the handler can identify the affected row without a separate lookup.
     */
    rowData?: Record<string, unknown>;
    /**
     * Flat row index — forwarded to row edit events when available.
     */
    rowIndex?: number;
}
/**
 * Defines valid state in DataTableRowEditor component.
 */
export interface DataTableRowEditorState {
    /**
     * Whether the row is currently being edited.
     */
    isEditing: boolean;
}
/**
 * Slot context exposed to the `children` render prop and on the component instance.
 */
export interface DataTableRowEditorExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
    /**
     * Whether the row is currently in edit mode.
     */
    isEditing: boolean;
}
/**
 * Instance of DataTableRowEditor component.
 */
export type DataTableRowEditorInstance = ComponentInstance<DataTableRowEditorProps, DataTableRowEditorState, DataTableRowEditorExposes>;
/**
 * Context value shared by RowEditor with its sub-components.
 */
export interface DataTableRowEditorContextValue {
    /**
     * Whether the row is in edit mode.
     */
    isEditing: boolean;
    /**
     * Row key for this editor.
     */
    rowKey: string | number;
    /**
     * Ref slot the Init button registers its DOM node with. RowEditor uses it to restore focus
     * when the row leaves edit mode.
     */
    initRef: React.MutableRefObject<HTMLElement | null>;
    /**
     * Ref slot the Save button registers its DOM node with. RowEditor uses it to move focus
     * when the row enters edit mode.
     */
    saveRef: React.MutableRefObject<HTMLElement | null>;
    /**
     * Start editing the row.
     */
    onInitClick: (event: React.MouseEvent) => void;
    /**
     * Save the row edit.
     */
    onSaveClick: (event: React.MouseEvent) => void;
    /**
     * Cancel the row edit.
     */
    onCancelClick: (event: React.MouseEvent) => void;
}
/**
 * Event re-exported from the headless layer so consumers can import it from the
 * primitive/UI barrel instead of reaching into headless. Mirrors `UseDataTableRowEditEvent`.
 */
export interface DataTableRowEditEvent extends UseDataTableRowEditEvent {
}
/**
 * Event re-exported from the headless layer so consumers can import it from the
 * primitive/UI barrel instead of reaching into headless. Mirrors `UseDataTableEditingEvent`.
 */
export interface DataTableEditingEvent extends UseDataTableEditingEvent {
}
